#include <vector>
#include <string>
#include <cstddef>
#include <omp.h>

struct Book {
   std::string title;
   int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
    const size_t n = books.size();
    long long globalBest = -1;

    #pragma omp parallel
    {
        long long localBest = -1;

        #pragma omp for nowait
        for (long long i = 0; i < static_cast<long long>(n); ++i) {
            if (books[static_cast<size_t>(i)].pages < 100) {
                if (i > localBest) localBest = i;
            }
        }

        #pragma omp critical
        {
            if (localBest > globalBest) globalBest = localBest;
        }
    }

    // If not found, return books.size() to indicate "no match"
    return (globalBest < 0) ? n : static_cast<size_t>(globalBest);
}
